# Extension-native adapter for exact promoted recipe lookup and verified attempt recording.
append_native = '''\n\nexport type InteractionRecipeStrategy =\n  | "ARIA_COMBOBOX"\n  | "ARIA_RADIO"\n  | "ARIA_BOOLEAN"\n  | "CUSTOM_DATE"\n  | "CUSTOM_MULTI_SELECT";\n\nexport type InteractionRecipeStatus = {\n  recipeId: string;\n  componentFingerprint: string;\n  semanticType: string;\n  siteOrigin: string;\n  strategy: InteractionRecipeStrategy;\n  state: "SHADOW" | "PROMOTED" | "ROLLED_BACK";\n  version: number;\n  actions: unknown[];\n  attemptInserted?: boolean;\n  verifiedAttempts?: number;\n  verifiedSuccesses?: number;\n};\n\nfunction parseInteractionRecipe(value: unknown): InteractionRecipeStatus | null {\n  if (value === null) return null;\n  const candidate = objectValue(value, "Interaction recipe");\n  const strategies = new Set([\n    "ARIA_COMBOBOX",\n    "ARIA_RADIO",\n    "ARIA_BOOLEAN",\n    "CUSTOM_DATE",\n    "CUSTOM_MULTI_SELECT",\n  ]);\n  const states = new Set(["SHADOW", "PROMOTED", "ROLLED_BACK"]);\n  if (typeof candidate.strategy !== "string" || !strategies.has(candidate.strategy)) {\n    throw new Error("Interaction recipe strategy is invalid");\n  }\n  if (typeof candidate.state !== "string" || !states.has(candidate.state)) {\n    throw new Error("Interaction recipe state is invalid");\n  }\n  if (!Array.isArray(candidate.actions)) {\n    throw new Error("Interaction recipe actions are invalid");\n  }\n  const result: InteractionRecipeStatus = {\n    recipeId: stringValue(candidate.recipeId, "Interaction recipeId"),\n    componentFingerprint: stringValue(\n      candidate.componentFingerprint,\n      "Interaction component fingerprint",\n    ),\n    semanticType: stringValue(candidate.semanticType, "Interaction semantic type"),\n    siteOrigin: stringValue(candidate.siteOrigin, "Interaction site origin"),\n    strategy: candidate.strategy as InteractionRecipeStrategy,\n    state: candidate.state as InteractionRecipeStatus["state"],\n    version: integerValue(candidate.version, "Interaction recipe version"),\n    actions: [...candidate.actions],\n  };\n  if (typeof candidate.attemptInserted === "boolean") {\n    result.attemptInserted = candidate.attemptInserted;\n  }\n  if (candidate.verifiedAttempts !== undefined) {\n    result.verifiedAttempts = integerValue(\n      candidate.verifiedAttempts,\n      "Interaction verified attempts",\n    );\n  }\n  if (candidate.verifiedSuccesses !== undefined) {\n    result.verifiedSuccesses = integerValue(\n      candidate.verifiedSuccesses,\n      "Interaction verified successes",\n    );\n  }\n  return result;\n}\n\nexport async function getPromotedInteractionRecipe(input: {\n  siteOrigin: string;\n  componentFingerprint: string;\n  semanticType: string;\n}): Promise<InteractionRecipeStatus | null> {\n  return parseInteractionRecipe(\n    await sendNative<unknown>({\n      type: "GET_INTERACTION_RECIPE",\n      payload: input,\n    }),\n  );\n}\n\nexport async function recordInteractionRecipeAttempt(input: {\n  attemptId: string;\n  applicationId: string;\n  siteOrigin: string;\n  componentFingerprint: string;\n  semanticType: string;\n  strategy: InteractionRecipeStrategy;\n  success: boolean;\n  verified: boolean;\n  failureReason: string | null;\n}): Promise<InteractionRecipeStatus> {\n  const result = parseInteractionRecipe(\n    await sendNative<unknown>({\n      type: "RECORD_INTERACTION_RECIPE_ATTEMPT",\n      payload: input,\n    }),\n  );\n  if (!result) throw new Error("Native recipe attempt returned no recipe");\n  return result;\n}\n'''
native_path = "apps/extension/src/messaging/native.ts"
native_content = read(native_path)
if "export type InteractionRecipeStrategy" in native_content:
    raise RuntimeError("Interaction recipe adapter already exists")
write(native_path, native_content.rstrip() + append_native + "\n")

# Service-worker learning is non-blocking: a missing native companion never makes guarded fill less safe.
replace_once(
    "apps/extension/src/background/service-worker.ts",
    '''  getNativeHealth,\n  markAIDraftUsed,''',
    '''  getNativeHealth,\n  getPromotedInteractionRecipe,\n  markAIDraftUsed,\n  recordInteractionRecipeAttempt,\n  type InteractionRecipeStrategy,''',
)
old_send = '''async function sendFillInstruction(\n  tabId: number,\n  instruction: FillInstruction,\n): Promise<FillResult[]> {\n  const response = (await chrome.tabs.sendMessage(\n    tabId,\n    {\n      type: "APPLY_FILL_INSTRUCTIONS",\n      instructions: [instruction],\n    },\n    { frameId: instruction.frameId },\n  )) as { results?: FillResult[] } | undefined;\n  return response?.results ?? [];\n}'''
new_send = '''const learnableStrategies = new Set<InteractionRecipeStrategy>([\n  "ARIA_COMBOBOX",\n  "ARIA_RADIO",\n  "ARIA_BOOLEAN",\n  "CUSTOM_DATE",\n  "CUSTOM_MULTI_SELECT",\n]);\n\nasync function sendFillInstruction(\n  tabId: number,\n  instruction: FillInstruction,\n): Promise<FillResult[]> {\n  const before = await getMergedPageForTab(tabId);\n  const control = before?.controls.find(\n    (candidate) => candidate.controlId === instruction.controlId,\n  );\n  const question = before?.questions.find(\n    (candidate) => candidate.controlId === instruction.controlId,\n  );\n  let siteOrigin: string | null = null;\n  try {\n    siteOrigin = before ? new URL(before.url).origin : null;\n  } catch {\n    siteOrigin = null;\n  }\n  let promotedRecipe: Awaited<\n    ReturnType<typeof getPromotedInteractionRecipe>\n  > = null;\n  if (\n    siteOrigin &&\n    control?.componentFingerprint &&\n    question &&\n    !question.sensitive\n  ) {\n    try {\n      promotedRecipe = await getPromotedInteractionRecipe({\n        siteOrigin,\n        componentFingerprint: control.componentFingerprint,\n        semanticType: question.semanticType,\n      });\n    } catch {\n      promotedRecipe = null;\n    }\n  }\n\n  const response = (await chrome.tabs.sendMessage(\n    tabId,\n    {\n      type: "APPLY_FILL_INSTRUCTIONS",\n      instructions: [instruction],\n    },\n    { frameId: instruction.frameId },\n  )) as { results?: FillResult[] } | undefined;\n  const results = response?.results ?? [];\n\n  return Promise.all(\n    results.map(async (result) => {\n      const strategy = result.strategy as InteractionRecipeStrategy | undefined;\n      if (\n        !siteOrigin ||\n        !control?.componentFingerprint ||\n        !question ||\n        question.sensitive ||\n        !strategy ||\n        !learnableStrategies.has(strategy)\n      ) {\n        return result;\n      }\n      const promotedAttempted =\n        promotedRecipe?.state === "PROMOTED" &&\n        promotedRecipe.strategy === strategy;\n      try {\n        const learned = await recordInteractionRecipeAttempt({\n          attemptId: crypto.randomUUID(),\n          applicationId: before?.applicationId ?? "unknown-application",\n          siteOrigin,\n          componentFingerprint: control.componentFingerprint,\n          semanticType: question.semanticType,\n          strategy,\n          success: result.status === "FILLED",\n          verified: true,\n          failureReason: result.status === "FILLED" ? null : result.reason,\n        });\n        return {\n          ...result,\n          recipeId: promotedRecipe?.recipeId ?? learned.recipeId,\n          recipeAttempted: promotedAttempted,\n          recipeSucceeded: promotedAttempted\n            ? result.status === "FILLED"\n            : undefined,\n        };\n      } catch {\n        return result;\n      }\n    }),\n  );\n}'''
replace_once("apps/extension/src/background/service-worker.ts", old_send, new_send)

# Direct advanced-control tests: exact temporal formats, no timezone guessing, true multi-select, rollback.
write(
    "apps/extension/src/content/advanced-controls.test.ts",
    '''// @vitest-environment jsdom\n\nimport { beforeEach, describe, expect, it } from "vitest";\nimport {\n  fillAriaMultiSelectControl,\n  fillStrictTemporalInput,\n} from "./advanced-controls";\n\nconst timing = {\n  optionTimeoutMs: 100,\n  pollIntervalMs: 5,\n  verificationTimeoutMs: 100,\n  stabilityQuietMs: 5,\n  stabilityTimeoutMs: 50,\n};\n\ndescribe("strict temporal controls", () => {\n  beforeEach(() => {\n    document.body.innerHTML = "";\n  });\n\n  it.each([\n    ["month", "2026-12"],\n    ["time", "17:45"],\n    ["datetime-local", "2026-12-17T17:45"],\n    ["week", "2026-W51"],\n  ])("fills canonical %s values exactly", (type, value) => {\n    const input = document.createElement("input");\n    input.type = type;\n    document.body.append(input);\n    expect(fillStrictTemporalInput(input, value)).toBe(true);\n    expect(input.value).toBe(value);\n  });\n\n  it.each([\n    ["month", "12/2026"],\n    ["time", "5:45 PM"],\n    ["datetime-local", "2026-12-17 17:45Z"],\n    ["week", "week 51 2026"],\n  ])("rejects non-canonical %s values without guessing", (type, value) => {\n    const input = document.createElement("input");\n    input.type = type;\n    document.body.append(input);\n    expect(fillStrictTemporalInput(input, value)).toBe(false);\n    expect(input.value).toBe("");\n  });\n});\n\ndescribe("ARIA multi-select", () => {\n  beforeEach(() => {\n    document.body.innerHTML = `\n      <label for="skills">Skills</label>\n      <button id="skills" aria-haspopup="listbox" aria-controls="skill-list" aria-expanded="false">Choose</button>\n      <div id="skill-list" role="listbox" aria-multiselectable="true">\n        <div role="option" data-value="Excel" aria-selected="false">Excel</div>\n        <div role="option" data-value="Power BI" aria-selected="false">Power BI</div>\n        <div role="option" data-value="Python" aria-selected="true">Python</div>\n      </div>\n    `;\n    const button = document.getElementById("skills")!;\n    button.addEventListener("click", () => button.setAttribute("aria-expanded", "true"));\n    for (const option of Array.from(document.querySelectorAll<HTMLElement>("[role='option']"))) {\n      option.addEventListener("click", () => {\n        option.setAttribute(\n          "aria-selected",\n          option.getAttribute("aria-selected") === "true" ? "false" : "true",\n        );\n      });\n    }\n  });\n\n  it("sets the exact requested set and removes extra selections", async () => {\n    const button = document.getElementById("skills") as HTMLElement;\n    const result = await fillAriaMultiSelectControl(\n      button,\n      '["Excel","Power BI"]',\n      timing,\n    );\n    expect(result).toBe(true);\n    const selected = Array.from(\n      document.querySelectorAll<HTMLElement>("[role='option'][aria-selected='true']"),\n    ).map((item) => item.dataset.value);\n    expect(selected).toEqual(["Excel", "Power BI"]);\n  });\n\n  it("fails closed when one requested option is ambiguous", async () => {\n    const list = document.getElementById("skill-list")!;\n    list.insertAdjacentHTML(\n      "beforeend",\n      '<div role="option" data-value="Excel" aria-selected="false">Excel</div>',\n    );\n    const before = Array.from(\n      document.querySelectorAll<HTMLElement>("[role='option']"),\n    ).map((item) => item.getAttribute("aria-selected"));\n    const result = await fillAriaMultiSelectControl(\n      document.getElementById("skills") as HTMLElement,\n      "Excel",\n      timing,\n    );\n    expect(result).toBe(false);\n    const after = Array.from(\n      document.querySelectorAll<HTMLElement>("[role='option']"),\n    ).map((item) => item.getAttribute("aria-selected"));\n    expect(after).toEqual(before);\n  });\n});\n''',
)

# Native message route tests prove learning is available through the actual host protocol boundary.
write(
    "apps/native-host/tests/test_native_interaction_recipe_messages.py",
    '''from __future__ import annotations\n\nfrom datetime import UTC, datetime\nfrom pathlib import Path\n\nfrom munshi_apply_native.database import Database\nfrom munshi_apply_native.native_messaging import handle\n\n\ndef create_database(tmp_path: Path) -> Database:\n    migrations = Path(__file__).resolve().parents[3] / "migrations"\n    database = Database(tmp_path / "test.sqlite", migrations)\n    database.migrate()\n    now = datetime.now(UTC).isoformat()\n    with database.connect() as connection:\n        connection.execute(\n            """\n            INSERT INTO applications (\n                application_id, job_id, status, resume_id, job_signal_score,\n                submitted_at, created_at, updated_at\n            ) VALUES ('app-1', NULL, 'DETECTED', NULL, NULL, NULL, ?, ?)\n            """,\n            (now, now),\n        )\n    return database\n\n\ndef attempt(index: int) -> dict[str, object]:\n    return {\n        "attemptId": f"attempt-{index}",\n        "applicationId": "app-1",\n        "siteOrigin": "https://jobs.example.test",\n        "componentFingerprint": "cfp-message",\n        "semanticType": "COUNTRY",\n        "strategy": "ARIA_COMBOBOX",\n        "success": True,\n        "verified": True,\n        "failureReason": None,\n    }\n\n\ndef test_native_recipe_messages_promote_and_lookup(tmp_path: Path) -> None:\n    database = create_database(tmp_path)\n    for index in range(3):\n        response = handle(\n            {\n                "type": "RECORD_INTERACTION_RECIPE_ATTEMPT",\n                "payload": attempt(index),\n            },\n            database,\n        )\n        assert response["ok"] is True\n    lookup = handle(\n        {\n            "type": "GET_INTERACTION_RECIPE",\n            "payload": {\n                "siteOrigin": "https://jobs.example.test",\n                "componentFingerprint": "cfp-message",\n                "semanticType": "COUNTRY",\n            },\n        },\n        database,\n    )\n    assert lookup["ok"] is True\n    assert lookup["data"] is not None\n    assert lookup["data"]["state"] == "PROMOTED"\n    assert lookup["data"]["strategy"] == "ARIA_COMBOBOX"\n''',
)

